          "words": [
            {"translit": "jamâna", "gloss": "a step (period) of time", "script": null},
            {"translit": "thamân", "gloss": "time", "script": null}
          ],
          "script_extra": null,
          "note": null,
          "quote": null
        },
        {
          "id": 13,
          "parent": 12,
          "lang": "Persian",
          "refs": "MON:1746",
