          "note": null,
          "quote": null
        },
        {
          "id": 16,
          "parent": 0,
          "lang": "Avestan / Old Persian",
          "refs": "BQT:2383",
          "words": [
            {"translit": "gâma", "gloss": "a step (period) of time", "script": null},
